import { targetDisplayName } from "./targetContext";

export const REPORT_DISCLAIMER =
  "For research and educational use only — not medical advice. The 0–100 knowledge-based triage score is a heuristic for prioritization (curated target rules and literature knowledge), not a validated predictor of binding, activity, or clinical success. Computational rankings are triage aids only; experimental validation (ADME, biochemical assays, clinical studies) is required before treating any candidate as a lead.";

export const REPORT_FOOTER =
  "Generated by PocketLink (https://pocketlink-nine.vercel.app/) — shareable research summary from browser session data.";

function mdEscape(value) {
  return String(value ?? "—").replace(/\|/g, "\\|").replace(/\n/g, " ");
}

function formatReportTimestamp(timestamp) {
  if (!timestamp) return new Date().toISOString();
  try {
    return new Date(timestamp).toLocaleString(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZoneName: "short",
    });
  } catch {
    return new Date(timestamp).toISOString();
  }
}

function stripMarkdownBold(text) {
  return String(text || "").replace(/\*\*(.*?)\*\*/g, "$1").replace(/\*(.*?)\*/g, "$1");
}

function joinLines(lines) {
  return lines.filter((line) => line != null && line !== "").join("\n");
}

function section(title, bodyLines) {
  return joinLines([`## ${title}`, "", ...bodyLines, ""]);
}

function table(headers, rows) {
  if (!rows?.length) return "_No data recorded in this session._\n";
  const headerLine = `| ${headers.join(" | ")} |`;
  const divider = `| ${headers.map(() => "---").join(" | ")} |`;
  const body = rows.map((row) => `| ${row.map((cell) => mdEscape(cell)).join(" | ")} |`);
  return joinLines([headerLine, divider, ...body, ""]);
}

export function sanitizeReportFilename(name) {
  return (
    String(name || "pocketlink-report")
      .replace(/[^\w-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 80) || "pocketlink-report"
  );
}

export function downloadMarkdown(filename, markdown) {
  const blob = new Blob([markdown], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `${sanitizeReportFilename(filename)}.md`;
  anchor.click();
  URL.revokeObjectURL(url);
}

function reportHeader(title, meta = {}) {
  return joinLines([
    `# ${title}`,
    "",
    `**Generated:** ${formatReportTimestamp(meta.timestamp)}`,
    meta.module ? `**Module:** ${meta.module}` : null,
    meta.sessionTitle ? `**Session:** ${meta.sessionTitle}` : null,
    "",
    `> ${REPORT_DISCLAIMER}`,
    "",
  ]);
}

function reportFooter() {
  return joinLines(["---", "", REPORT_FOOTER]);
}

function rankingSourceLabel(source, usedLlm, fromDailyCache) {
  if (usedLlm) return "Ranked with OpenAI for this specific target";
  if (source === "cache" || fromDailyCache) return "Reused cached scores for this (compound, PDB) pair";
  if (source === "llm") return "Ranked with OpenAI for this specific target";
  return "Ranked with PocketLink's target-aware heuristic-v2 model";
}

function formatReasoning(row) {
  if (Array.isArray(row?.reasoning) && row.reasoning.length) return row.reasoning.slice(0, 3).join("; ");
  const merged = [...(row?.strengths || []), ...(row?.concerns || [])];
  return merged.slice(0, 3).join("; ") || "—";
}

export function buildAgentReportMarkdown(report, meta = {}) {
  if (!report) return "";

  const exec = report.executiveSummary;
  const step1 = report.steps?.[1];
  const step2 = report.steps?.[2];
  const step3 = report.steps?.[3];
  const step4 = report.steps?.[4];
  const topCandidates =
    (Array.isArray(step3?.data?.top5) && step3.data.top5.length ? step3.data.top5 : null) ||
    (Array.isArray(step3?.data?.ranking) ? step3.data.ranking.slice(0, 5) : []);

  const lines = [
    reportHeader("PocketLink Autonomous Research Agent Report", {
      timestamp: meta.timestamp || report.completedAt || Date.now(),
      module: "Autonomous Research Agent",
      sessionTitle: report.goal || meta.title,
    }),
    section("Executive Summary", [
      `- **Objective:** ${report.goal || "—"}`,
      `- **Disease:** ${exec?.disease || report.diseaseResolved?.name || "—"} (${exec?.diseaseId || report.diseaseResolved?.id || "N/A"})`,
      `- **Target:** ${exec?.targetSymbol || "—"} — ${exec?.targetOneLineWhy || "Validated disease association"}`,
      exec?.pivotedFrom ? `- **Pivot note:** Switched from ${exec.pivotedFrom}` : null,
      `- **PDB structure:** ${exec?.pdbId || "—"} (${exec?.pdbResolution || "Experimental"}) · selection score ${exec?.targetSelectionScore ?? "—"}/100`,
      `- **Lead approved drug:** ${exec?.leadDrugName || "—"} (CID ${exec?.leadDrugCid || "N/A"}, knowledge-based triage score ${exec?.repurposingScore ?? "—"}/100)`,
      `- **Primary indication:** ${exec?.primaryIndication || "N/A"}`,
      `- **Verdict:** ${exec?.verdict || "Computational assessment complete"}`,
      `- **Pipeline status:** ${report.status || "—"}${report.haltReason ? ` — ${stripMarkdownBold(report.haltReason)}` : ""}`,
      report.totalDurationMs ? `- **Duration:** ${Math.round(report.totalDurationMs / 1000)}s` : null,
    ]),
  ];

  if (step1) {
    lines.push(
      section("Step 1 — Target Discovery", [
        step1.narration ? stripMarkdownBold(step1.narration) : null,
        step1.data?.primaryTarget
          ? `- **Primary target:** ${step1.data.primaryTarget.symbol} (${step1.data.primaryTarget.name || "—"}) · novelty ${step1.data.primaryTarget.noveltyScore ?? "N/A"}/100 · genetic ${step1.data.primaryTarget.geneticScore != null ? `${(step1.data.primaryTarget.geneticScore * 100).toFixed(0)}%` : "N/A"} · approved drugs ${step1.data.primaryTarget.drugCount ?? 0}`
          : null,
        step1.data?.backupTarget
          ? `- **Backup target:** ${step1.data.backupTarget.symbol} (${step1.data.backupTarget.name || "—"})`
          : null,
        Array.isArray(step1.data?.noveltyTargets) && step1.data.noveltyTargets.length
          ? "### Evaluated targets\n\n" +
              table(
                ["Rank", "Gene", "Novelty", "Overall", "Genetic", "Drugs"],
                step1.data.noveltyTargets.slice(0, 25).map((row, idx) => [
                  idx + 1,
                  row.symbol || "—",
                  row.noveltyScore != null ? row.noveltyScore.toFixed(1) : "—",
                  row.overallScore != null ? row.overallScore.toFixed(2) : "—",
                  row.geneticScore != null ? `${(row.geneticScore * 100).toFixed(0)}%` : "—",
                  row.drugCount ?? 0,
                ])
              )
          : null,
      ])
    );
  }

  if (step2) {
    const pdb = step2.data?.selectedStructure;
    lines.push(
      section("Step 2 — PDB Selection", [
        step2.narration ? stripMarkdownBold(step2.narration) : null,
        pdb
          ? `- **Selected PDB:** ${pdb.id || pdb.pdb_id || "—"} · resolution ${pdb.resolution || "N/A"} · score ${pdb.score ?? pdb.targetSelectionScore ?? "—"}/100`
          : null,
        pdb?.ligand?.name || pdb?.ligands?.[0]?.name
          ? `- **Co-crystal ligand:** ${pdb.ligand?.name || pdb.ligands?.[0]?.name}`
          : null,
        step2.data?.pivoted ? `- **Pivot:** ${stripMarkdownBold(step2.data.pivotReason || "Used backup target after primary structure failed viability checks.")}` : null,
      ])
    );
  }

  if (step3) {
    lines.push(
      section("Step 3 — Repurposing Screen", [
        step3.narration ? stripMarkdownBold(step3.narration) : null,
        step3.data?.librarySize ? `- **Library screened:** ${step3.data.librarySize.toLocaleString()} approved drugs` : null,
        step3.data?.scoredCount ? `- **Shortlist scored:** ${step3.data.scoredCount}` : null,
        topCandidates.length
          ? "### Top candidates\n\n" +
              table(
                ["Rank", "Drug", "CID", "Triage score", "Indication", "Reasoning"],
                topCandidates.map((row, idx) => [
                  idx + 1,
                  row.name || "—",
                  row.cid || "—",
                  `${row.score ?? "—"}/100`,
                  row.indication || "—",
                  formatReasoning(row),
                ])
              )
          : "_No ranking recorded._",
      ])
    );
  }

  if (step4) {
    const candidate = step4.data?.candidate;
    const critique = step4.data?.critique;
    const concerns = critique?.case_against?.concerns;
    lines.push(
      section("Step 4 — Adversarial Critique (The Case Against)", [
        step4.narration ? stripMarkdownBold(step4.narration) : null,
        candidate ? `- **Lead evaluated:** ${candidate.name} (${candidate.score ?? "—"}/100)` : null,
        exec?.critiqueSummary ? `- **Critique summary:** ${exec.critiqueSummary}` : null,
        exec?.keyConcern ? `- **Primary concern:** ${exec.keyConcern}${exec.keyConcernDetail ? ` — ${exec.keyConcernDetail}` : ""}` : null,
        Array.isArray(concerns) && concerns.length
          ? "### Itemized concerns\n\n" +
              concerns.map((item) => `- **${item.issue}:** ${item.detail}`).join("\n")
          : null,
        critique?.case_against?.overall_assessment
          ? `- **Overall assessment:** ${critique.case_against.overall_assessment}`
          : null,
      ])
    );
  }

  lines.push(
    section("Methodology & Limitations", [
      "- Agent pipeline uses Open Targets associations, RCSB PDB structure filters, knowledge-based triage scores (heuristic-v2), and optional LLM adversarial critique.",
      "- Triage scores reflect curated target rules, pocket/ligand context, and drug-likeness heuristics — not validated binding or clinical activity.",
      "- Adversarial critique highlights plausible liabilities; it is not a substitute for experimental orthogonal assays.",
      `- ${REPORT_DISCLAIMER}`,
    ]),
    reportFooter()
  );

  return joinLines(lines);
}

export function buildDockingReportMarkdown({
  targetTitle,
  pdbId,
  compoundName,
  smiles,
  cid,
  dockingResults,
  activePose,
  timestamp,
}) {
  if (!dockingResults || !activePose) return "";

  const lines = [
    reportHeader("PocketLink Molecular Docking Report", {
      timestamp,
      module: "Molecular Docking Simulation",
      sessionTitle: `${compoundName || "Ligand"} vs ${targetTitle || pdbId || "target"}`,
    }),
    section("Simulation Inputs", [
      `- **Target:** ${targetTitle || "—"} (PDB: ${pdbId || "—"})`,
      `- **Ligand:** ${compoundName || "—"}${cid ? ` (CID ${cid})` : ""}`,
      `- **SMILES:** \`${smiles || "—"}\``,
      dockingResults.target?.pocketResiduesCount
        ? `- **Pocket residues analyzed:** ${dockingResults.target.pocketResiduesCount} within ${dockingResults.target.boxSize || "—"} Å cavity`
        : null,
    ]),
    section("Selected Binding Mode", [
      `- **Pose rank:** ${activePose.rank}`,
      `- **Predicted ΔG_bind:** ${activePose.deltaG} kcal/mol`,
      `- **Estimated Ki:** ${activePose.kiFormatted}`,
      `- **RMSD to best pose:** ${activePose.rmsd} Å`,
      `- **Hydrogen bonds:** ${activePose.hbondCount}`,
      `- **Hydrophobic contacts:** ${activePose.hydrophobicCount}`,
      activePose.components
        ? [
            "",
            "### Energy decomposition",
            "",
            `- Van der Waals: ${activePose.components.vdw} kcal/mol`,
            `- Hydrogen bonding: ${activePose.components.hbond} kcal/mol`,
            `- Electrostatic: ${activePose.components.electrostatic} kcal/mol`,
            `- Desolvation reward: ${activePose.components.desolvation} kcal/mol`,
            `- Torsional penalty: +${activePose.components.torsional} kcal/mol`,
          ].join("\n")
        : null,
      Array.isArray(activePose.residueBreakdown) && activePose.residueBreakdown.length
        ? "### Top interacting residues\n\n" +
            table(
              ["Residue", "Min distance (Å)", "Energy (kcal/mol)", "H-bonds"],
              activePose.residueBreakdown.slice(0, 12).map((r) => [
                `${r.resName}-${r.resSeq}`,
                r.minDistance,
                r.energy,
                r.hbonds,
              ])
            )
        : null,
    ]),
  ];

  if (Array.isArray(dockingResults.rankedPoses) && dockingResults.rankedPoses.length) {
    lines.push(
      section("Pose Clusters", [
        table(
          ["Pose", "ΔG (kcal/mol)", "Est. Ki", "RMSD (Å)", "H-bonds"],
          dockingResults.rankedPoses.map((p) => [
            p.rank,
            p.deltaG,
            p.kiFormatted,
            p.rmsd?.toFixed ? p.rmsd.toFixed(2) : p.rmsd,
            p.hbondCount,
          ])
        ),
      ])
    );
  }

  lines.push(
    section("Methodology & Limitations", [
      "- Empirical force-field scoring and Monte Carlo pose optimization in-browser (Morris et al. 2009; Trott & Olson 2010).",
      "- Predicted ΔG and Ki are computational estimates — not experimental binding measurements.",
      "- Pose quality depends on receptor preparation, pocket definition, and ligand protonation/tautomer choices not modeled here.",
      `- ${REPORT_DISCLAIMER}`,
    ]),
    reportFooter()
  );

  return joinLines(lines);
}

export function buildBenchReportMarkdown({ protein, candidates, aiResult, timestamp, title }) {
  if (!aiResult) return "";

  const targetName = targetDisplayName(protein);
  const pdbId = protein?.id || protein?.pdb_id || aiResult.target?.pdb_id || "—";
  const ranking = Array.isArray(aiResult.ranking) ? aiResult.ranking : [];

  const lines = [
    reportHeader("PocketLink Staging Bench Report", {
      timestamp,
      module: "Staging Bench",
      sessionTitle: title || `${targetName || "Target"} candidate ranking`,
    }),
    section("Target Context", [
      `- **Target / structure:** ${targetName || "—"} (PDB: ${pdbId})`,
      protein?.targetSelectionScore != null ? `- **Target selection score:** ${protein.targetSelectionScore}/100` : null,
      protein?.resolution ? `- **Resolution:** ${protein.resolution}` : null,
      protein?.gene ? `- **Gene:** ${protein.gene}` : null,
      `- **Candidates analyzed:** ${candidates?.length || ranking.length}`,
    ]),
    section("Ranking Results", [
      aiResult.recommended
        ? `- **Recommended lead:** CID ${aiResult.recommended.cid || "—"} · ${aiResult.recommended.score ?? "—"}/100 — ${aiResult.recommended.reason || "Best fit for this structure"}`
        : null,
      ranking.length
        ? table(
            ["Rank", "Compound", "CID", "Triage score", "Key reasons"],
            ranking.map((row, idx) => [
              idx + 1,
              row.name || row.displayName || "—",
              row.cid || row.CID || "—",
              `${row.score ?? "—"}/100`,
              formatReasoning(row),
            ])
          )
        : "_No ranking rows recorded._",
      aiResult.summary ? `\n${aiResult.summary}` : null,
    ]),
    section("Methodology & Limitations", [
      `- **Source:** ${rankingSourceLabel(aiResult.source)}`,
      ...(Array.isArray(aiResult.limitations) ? aiResult.limitations.map((item) => `- ${item}`) : []),
      `- ${REPORT_DISCLAIMER}`,
    ]),
    reportFooter(),
  ];

  return joinLines(lines);
}

export function buildRepurposingReportMarkdown({ result, timestamp, title }) {
  if (!result) return "";

  const target = result.target || {};
  const targetName = target.name || targetDisplayName(target) || "Selected target";
  const ranking = Array.isArray(result.ranking) ? result.ranking : [];
  const topRows = ranking.slice(0, 20);

  const lines = [
    reportHeader("PocketLink Drug Repurposing Screen Report", {
      timestamp,
      module: "Drug Repurposing Screen",
      sessionTitle: title || `${targetName} (${target.pdb_id || "—"})`,
    }),
    section("Screen Summary", [
      `- **Target:** ${targetName} (PDB: ${target.pdb_id || "—"})`,
      result.librarySize ? `- **Approved-drug library:** ${result.librarySize.toLocaleString()} compounds` : null,
      result.scoredCount ? `- **Compounds scored:** ${result.scoredCount}` : null,
      result.recommended
        ? `- **Lead candidate:** ${result.recommended.name} (CID ${result.recommended.cid}, ${result.recommended.score}/100)`
        : null,
      result.summary ? `- **Summary:** ${result.summary}` : null,
      `- **Source:** ${rankingSourceLabel(result.source, result.usedLlm, result.fromDailyCache)}`,
      result.degraded ? `- **Note:** ${result.warning || "Structure lacked sufficient pocket/ligand context — scores reflect general drug-likeness only."}` : null,
    ]),
    section("Top Library Ranking", [
      topRows.length
        ? table(
            ["Rank", "Drug", "CID", "Triage score", "Approved indication", "Reasoning"],
            topRows.map((row, idx) => [
              idx + 1,
              row.name || "—",
              row.cid || "—",
              `${row.score ?? "—"}/100`,
              row.indication || "—",
              formatReasoning(row),
            ])
          )
        : "_No ranking recorded._",
      ranking.length > topRows.length
        ? `\n_Showing top ${topRows.length} of ${ranking.length} scored compounds._`
        : null,
    ]),
    section("Methodology & Limitations", [
      "- Screens bundled approved-drug library with knowledge-based triage scoring (heuristic-v2: pocket geometry, co-crystal ligand, pharmacophore bands).",
      "- Triage scores prioritize hypotheses for follow-up; they are not validated activity or binding predictors.",
      result.excluded?.length
        ? `- Pre-filter excluded ${result.excluded.length} entries (missing SMILES, extreme MW, or severe Lipinski/Veber failures).`
        : null,
      `- ${REPORT_DISCLAIMER}`,
    ]),
    reportFooter(),
  ];

  return joinLines(lines);
}

export function buildTargetDiscoveryReportMarkdown({ result, query, view = "novelty", timestamp, title }) {
  if (!result) return "";

  const disease = result.disease || {};
  const rows = view === "established" ? result.established || [] : result.novelty || [];
  const diseaseName = disease.name || query || "Selected disease";

  const lines = [
    reportHeader("PocketLink Target Discovery Report", {
      timestamp,
      module: "Target Discovery",
      sessionTitle: title || diseaseName,
    }),
    section("Query & Disease Resolution", [
      `- **Search query:** ${query || "—"}`,
      `- **Resolved disease:** ${diseaseName} (${disease.id || "N/A"})`,
      disease.associationCount
        ? `- **Open Targets associations retrieved:** ${disease.associationCount.toLocaleString()} (showing top ${result.fetchedCount || rows.length})`
        : null,
      `- **View:** ${view === "established" ? "Well-established targets" : "Underexplored (novelty-ranked)"}`,
      result.fromCache ? "- **Data source:** Reused cached Open Targets results (24h TTL)" : "- **Data source:** Live Open Targets GraphQL query",
    ]),
    section(`${view === "established" ? "Established" : "High-novelty"} Targets`, [
      rows.length
        ? table(
            ["Rank", "Gene", "Novelty", "Genetic", "Drugs", "Summary"],
            rows.slice(0, 40).map((row, idx) => [
              idx + 1,
              row.symbol || "—",
              row.noveltyScore != null ? row.noveltyScore.toFixed(1) : "—",
              row.geneticScore != null ? `${(row.geneticScore * 100).toFixed(0)}%` : "—",
              row.drugCount ?? 0,
              row.explanation || "—",
            ])
          )
        : "_No targets passed the evidence threshold in this view._",
    ]),
    section("Methodology & Limitations", [
      "- Genetic associations and drug counts come from the Open Targets Platform.",
      "- Novelty score is a PocketLink ranking (biology signal × drug saturation), not Open Targets' own novelty field.",
      "- High novelty indicates a hypothesis to follow up — not proof that a target is druggable or safe to modulate.",
      `- ${REPORT_DISCLAIMER}`,
    ]),
    reportFooter(),
  ];

  return joinLines(lines);
}

export function buildHistoryEntryReportMarkdown(item) {
  if (!item?.type) return "";

  switch (item.type) {
    case "agent-run":
      return buildAgentReportMarkdown(item.snapshot?.report, {
        timestamp: item.timestamp,
        title: item.title,
      });
    case "staging-bench":
      return buildBenchReportMarkdown({
        protein: item.snapshot?.protein,
        candidates: item.snapshot?.candidates,
        aiResult: item.snapshot?.aiResult,
        timestamp: item.timestamp,
        title: item.title,
      });
    case "repurposing-run":
      return buildRepurposingReportMarkdown({
        result: {
          ...item.snapshot,
          target: item.snapshot?.target,
          ranking: item.snapshot?.topCandidates || item.snapshot?.ranking,
          scoredCount: item.snapshot?.totalDrugs || item.snapshot?.scoredCount,
        },
        timestamp: item.timestamp,
        title: item.title,
      });
    case "target-discovery":
      return buildTargetDiscoveryReportMarkdown({
        result: item.snapshot?.result,
        query: item.snapshot?.query || item.inputs?.query,
        view: item.snapshot?.view || "novelty",
        timestamp: item.timestamp,
        title: item.title,
      });
    case "pdb-search":
      return joinLines([
        reportHeader("PocketLink PDB Target Search Report", {
          timestamp: item.timestamp,
          module: "PDB Target Search",
          sessionTitle: item.title,
        }),
        section("Selected Structure", [
          `- **Query:** ${item.inputs?.query || item.snapshot?.query || "—"}`,
          `- **PDB ID:** ${item.inputs?.pdbId || item.snapshot?.protein?.id || "—"}`,
          item.snapshot?.protein?.title ? `- **Title:** ${item.snapshot.protein.title}` : null,
          item.snapshot?.protein?.targetSelectionScore != null
            ? `- **Target selection score:** ${item.snapshot.protein.targetSelectionScore}/100`
            : null,
          item.snapshot?.protein?.resolution ? `- **Resolution:** ${item.snapshot.protein.resolution}` : null,
        ]),
        section("Methodology & Limitations", [
          "- Structure selection uses PocketLink Target Selection Score (resolution, ligand, pocket completeness).",
          `- ${REPORT_DISCLAIMER}`,
        ]),
        reportFooter(),
      ]);
    default:
      return joinLines([
        reportHeader("PocketLink Session Report", {
          timestamp: item.timestamp,
          module: item.type,
          sessionTitle: item.title,
        }),
        "```json",
        JSON.stringify(item.snapshot || {}, null, 2),
        "```",
        "",
        reportFooter(),
      ]);
  }
}

export function defaultReportFilename(prefix, detail) {
  const stamp = new Date().toISOString().slice(0, 10);
  return sanitizeReportFilename(`${prefix}-${detail || "session"}-${stamp}`);
}
